import { readFile, writeFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { buildPrototypeTokenKit, readKitInputs } from '../../frontend/scripts/prototype-token-kit.mjs';

const lf = value => value.replace(/\r\n/g, '\n');
const clean = value => lf(value).replace(/[\t ]+$/gm, '');
export async function renderStyles() {
  return {
    'tokens.css': clean(buildPrototypeTokenKit(readKitInputs())['tokens.css']),
    'styles.css': `/* Generated by node tools/requirements-workspace/build-styles.mjs. */\n${clean(await readFile(new URL('./public/styles.input.css', import.meta.url), 'utf8'))}`,
  };
}
export async function stylesAreCurrent() {
  for (const [name, content] of Object.entries(await renderStyles())) {
    if (lf(await readFile(new URL(`./public/${name}`, import.meta.url), 'utf8')) !== lf(content)) return false;
  }
  return true;
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  if (process.argv.slice(2).some(arg => arg !== '--check')) throw new Error('usage: build-styles.mjs [--check]');
  if (process.argv.includes('--check')) {
    if (!await stylesAreCurrent()) { console.error('Requirements workspace styles are stale. Run node tools/requirements-workspace/build-styles.mjs'); process.exitCode = 1; }
  } else for (const [name, content] of Object.entries(await renderStyles())) await writeFile(new URL(`./public/${name}`, import.meta.url), content);
}
